300	    /**
301	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
302	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
303	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
304	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
305	     *
306	     * @throws DisposableEmailDomainException if the email domain is blocklisted
307	     */
308	    private void assertEmailDomainAllowed(Owner owner) {
309	        String email = owner.getEmail();
310	        if (email == null) {
311	            return;
312	        }
313	        int at = email.lastIndexOf('@');
314	        if (at < 0) {
